function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 50000) return 'nums needs 1 to 50000 values.';
  for (let i = 0; i < nums.length; i++) {
    if (!Number.isInteger(nums[i]) || nums[i] < 1 || nums[i] > 1e7) return 'Each value of nums is an integer from 1 to 10^7.';
    if (i > 0 && nums[i] <= nums[i - 1]) return 'nums must be strictly increasing (sorted, no duplicates).';
  }
  if (!Number.isInteger(k) || k < 1 || k > 1e8) return 'k is an integer from 1 to 10^8.';
  return null;
}

