function missingElement(nums, k) {
  const missingBefore = (i) => nums[i] - nums[0] - i;
  let left = 0;
  let right = nums.length - 1;

  while (left < right) {
    const mid = Math.ceil((left + right) / 2);
    if (missingBefore(mid) < k) {
      left = mid;
    } else {
      right = mid - 1;
    }
  }
  return nums[left] + k - missingBefore(left);
}

