function missingElement(nums, k) {
  let remaining = k;
  for (let i = 1; i < nums.length; i++) {
    const gap = nums[i] - nums[i - 1] - 1;
    if (remaining <= gap) return nums[i - 1] + remaining;
    remaining -= gap;
  }
  return nums[nums.length - 1] + remaining;
}

